-- City Café batch 04: recettes. Generated from city-cafe-recipes-batch-04.json.
BEGIN;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- Keep ingredient JSON category labels aligned with the canonical ingredient catalog.
UPDATE public.recipes AS recipe
SET ingredients = (
  SELECT jsonb_agg(jsonb_set(item.ingredient, '{category}', to_jsonb(canonical.category), true) ORDER BY item.ordinality)
  FROM jsonb_array_elements(recipe.ingredients) WITH ORDINALITY AS item(ingredient, ordinality)
  JOIN public.ingredients AS canonical ON canonical.name = item.ingredient->>'name'
)
WHERE recipe.id IN ('city-cafe-rosti-pizza-tomate-mozzarella-bufala', 'city-cafe-pizza-maison-legumes-rotis', 'city-cafe-pizza-trois-fromages-champignons-roquette', 'city-cafe-pizza-legumes-automne-ricotta-herbes', 'city-cafe-margherita-quatre-fromages-tomates-cerises');

-- Keep recipe image choices in sync if reviewed later.
UPDATE public.recipes AS recipe
SET image_url = image.image_url
FROM (VALUES
  ('city-cafe-rosti-pizza-tomate-mozzarella-bufala', 'https://images.pexels.com/photos/30232158/pexels-photo-30232158.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-pizza-maison-legumes-rotis', 'https://images.pexels.com/photos/30818094/pexels-photo-30818094.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-pizza-trois-fromages-champignons-roquette', 'https://images.pexels.com/photos/17478671/pexels-photo-17478671.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-pizza-legumes-automne-ricotta-herbes', 'https://images.pexels.com/photos/7362681/pexels-photo-7362681.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-margherita-quatre-fromages-tomates-cerises', 'https://images.pexels.com/photos/33457997/pexels-photo-33457997.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
) AS image(id, image_url)
WHERE recipe.id = image.id;

COMMIT;
